  "ledtrad": "<p>Hur långt ligger något av värdena från medelvärdet?</p>",
  "svarstyp": "numeriskt",
  "rättSvar": 0,
  "tolerans": 0,
  "svarFormat": "numeriskt",
  "svarEnhet": "h"
