  "traningsniva": 4,
  "arbetsinsats": 2,
  "ledtrad": "<p>Dra en linje från A genom D. Använd yttervinkelsatsen i de två trianglar som bildas.</p>",
  "svarstyp": "numeriskt",
  "rättSvar": 100,
  "tolerans": 0,
