  "självrättning": true,
  "traningsniva": 2,
  "arbetsinsats": 1,
  "ledtrad": "<p>I GeoGebras statistikverktyg (Tvåvariabelanalys) visas r bland statistiken.</p>",
  "svarstyp": "numeriskt",
  "rättSvar": 0.999,
  "tolerans": 0.0005,
  "svarFormat": "numeriskt"
