  "niva": "C",
  "poang": "0/1/0",
  "t": "<p>Talen 5, 9 och \\(x\\) har medelvärdet 9.</p><p>Bestäm \\(x\\) och standardavvikelsen Sx för de tre talen.</p>",
  "s": "<div class=\"facit-v2 facit-stegvis\"><ol class=\"facit-steglista\" role=\"list\"><li><p class=\"facit-rubrik\">Medelvärdet bestämmer x</p><div class=\"facit-matte\">\\[\\frac{5+9+x}{3}=9\\ \\Rightarrow\\ x=27-14=13\\]</div></li><li><p class=\"facit-rubrik\">Medelvärdet 9 för 5, 9 och 13</p><div class=\"facit-matte\">\\[\\bar x=\\frac{27}{3}=9\\]</div></li><li><p class=\"facit-rubrik\">Kvadrerade avvikelser från 9</p><div class=\"facit-matte\">\\[(5-9)^2+(9-9)^2+(13-9)^2\\]</div><div class=\"facit-matte\">\\[=16+0+16=32\\]</div></li><li><p class=\"facit-rubrik\">Sx för de tre talen</p><div class=\"facit-matte\">\\[S_x=\\sqrt{\\frac{32}{3-1}}=4{,}00\\]</div></li></ol><p class=\"facit-svar\"><strong>Svar:</strong> \\(x=13\\) och \\(S_x=4\\).</p></div>",
  "familj": "Beräkna och tolka standardavvikelse",
  "formaga": [
    "procedur",
    "problemlösning"
  ],
  "miniräknare": true,
  "geogebra": true,
  "självrättning": true,
  "ledtrad": "<p>Bestäm först \\(x\\) med hjälp av medelvärdet.</p>",
  "spel": true,
  "traningsniva": 3,
  "arbetsinsats": 2,
  "svarstyp": "flera_delar",
