  "familj": "Substitution med parametrar och resonemang",
  "formaga": [
    "begrepp"
  ],
  "miniräknare": false,
  "geogebra": false,
  "spel": true,
  "självrättning": true,
  "traningsniva": 1,
  "arbetsinsats": 1,
  "ledtrad": "<p>Subtrahera 2x från båda leden.</p>",
  "svarstyp": "alternativ",
  "rättSvar": null,
  "tolerans": null,
  "alternativ": [
    {
      "txt": "y = 7 − 2x",
      "ratt": true
    },
    {
      "txt": "y = 7 + 2x",
      "ratt": false,
      "kommentar": "2x ska subtraheras från båda leden."
    },
    {
      "txt": "y = 2x − 7",
      "ratt": false,
      "kommentar": "Tecknen har bytts fel."
    },
    {
      "txt": "y = (7 − x)/2",
      "ratt": false,
      "kommentar": "Det är x som har koefficienten 2, inte y."
    }
  ]
