    "självrättning": true,
    "traningsniva": 1,
    "arbetsinsats": 1,
    "ledtrad": "<p>Elin har bara multiplicerat de första och de sista termerna.</p>",
    "svarstyp": "alternativ",
    "rättSvar": null,
    "tolerans": null,
    "alternativ": [
      {
        "txt": "\\(x^2-2x-15\\)",
        "ratt": true
      },
      {
        "txt": "\\(x^2+2x-15\\)",
        "ratt": false,
        "kommentar": "\\(-5x+3x\\) blir \\(-2x\\)."
      },
      {
        "txt": "\\(x^2-8x-15\\)",
        "ratt": false,
        "kommentar": "Termen \\(3x\\) ska vara positiv."
      },
      {
        "txt": "\\(x^2-2x+15\\)",
        "ratt": false,
        "kommentar": "\\(3\\cdot(-5)=-15\\)."
      }
    ]
