    "ledtrad": "<p>Utveckla båda kvadraterna. Vilka termer tar ut varandra?</p>",
    "svarstyp": "uttryck",
    "svarFormat": "förenklat_polynom",
    "rättSvar": "2x^2+18",
    "tolerans": 0
