    "arbetsinsats": 2,
    "ledtrad": "<p>Arean ökar med \\((x+3)^2-x^2\\). Förenkla det uttrycket först.</p>",
    "svarstyp": "numeriskt",
    "svarFormat": "numeriskt",
    "rättSvar": 11,
    "tolerans": 0
