    "traningsniva": 3,
    "arbetsinsats": 2,
    "ledtrad": "<p>Sätt \\(F=C\\) och lös ekvationen.</p>",
    "svarstyp": "numeriskt",
    "svarFormat": "numeriskt",
    "rättSvar": -40,
    "tolerans": 0
