    "självrättning": true,
    "traningsniva": 3,
    "arbetsinsats": 2,
    "ledtrad": "<p>Sätt in \\(x=3\\) och \\(x=7\\) i \\(kx+m\\). Vad händer med m?</p>",
    "svarstyp": "numeriskt",
    "svarFormat": "numeriskt",
    "rättSvar": -2,
    "tolerans": 0
