    "traningsniva": 2,
    "arbetsinsats": 1,
    "ledtrad": "<p>\\(k_1\\cdot k_2=-1\\). En linje genom origo har \\(m=0\\).</p>",
    "svarstyp": "uttryck",
    "svarFormat": "uttryck",
    "rättSvar": "y=1.5x",
    "tolerans": 0
