    "självrättning": true,
    "traningsniva": 1,
    "arbetsinsats": 1,
    "ledtrad": "<p>Förhållandet mellan höjd och skugga är detsamma för pinnen och flaggstången.</p>",
    "svarstyp": "numeriskt",
    "rättSvar": 8.8,
    "tolerans": 0,
    "svarFormat": "numeriskt",
    "svarEnhet": "m"
