    "traningsniva": 3,
    "arbetsinsats": 2,
    "ledtrad": "<p>Läs av ungefär i figuren. Skriv sedan \\(0{,}5^x=\\frac{1}{2^x}\\).</p>",
    "svarstyp": "numeriskt",
    "svarFormat": "numeriskt",
    "rättSvar": 2.5,
