    "traningsniva": 3,
    "arbetsinsats": 2,
    "ledtrad": "<p>Gå två steg bakåt från \\(x=2\\): dela med \\(a\\) två gånger.</p>",
    "svarstyp": "numeriskt",
    "svarFormat": "numeriskt",
    "rättSvar": 200,
    "tolerans": 0
