    "självrättning": true,
    "traningsniva": 3,
    "arbetsinsats": 2,
    "ledtrad": "<p>Bestäm först skärningspunktens y-värde.</p>",
    "svarstyp": "numeriskt",
    "svarFormat": "numeriskt",
    "rättSvar": 2,
