    "arbetsinsats": 1,
    "ledtrad": "<p>Sätt in x och z i den första ekvationen.</p>",
    "svarstyp": "numeriskt",
    "svarFormat": "numeriskt",
    "rättSvar": 5,
    "tolerans": 0
