    "ledtrad": "<p>BD hör ihop med AB och DC med AC.</p>",
    "svarstyp": "numeriskt",
    "rättSvar": 18,
    "tolerans": 0,
    "svarFormat": "numeriskt",
    "svarEnhet": "cm"
