    "självrättning": true,
    "traningsniva": 3,
    "arbetsinsats": 2,
    "ledtrad": "<p>Vilken båge står vinkeln CAD på? Hur stor är medelpunktsvinkeln för den?</p>",
    "svarstyp": "numeriskt",
    "rättSvar": 22.5,
    "tolerans": 0,
    "svarFormat": "numeriskt",
    "svarEnhet": "°"
