    "traningsniva": 3,
    "arbetsinsats": 2,
    "ledtrad": "<p>Minimipunkten \\((p,\\ q)\\) ger den kvadratkompletterade formen \\((x-p)^2+q\\). Utveckla den sedan.</p>",
    "svarstyp": "flera_delar",
    "rättSvar": [
      -6,
      11
    ],
    "tolerans": [
      0,
      0
    ],
